/**
 * 纯视图层几何信息：节点在画布上的位置和尺寸。
 * 与业务数据 (MindNode) 分离，避免 Model 污染 View 状态。
 */
public final class NodeLayout {
 private int x;
 private int y;
 private int width;
 private int height;

 public NodeLayout() {
 }

 public NodeLayout(int x, int y, int width, int height) {
 this.x = x;
 this.y = y;
 this.width = width;
 this.height = height;
 }

 public int getX() { return x; }
 public void setX(int x) { this.x = x; }

 public int getY() { return y; }
 public void setY(int y) { this.y = y; }

 public int getWidth() { return width; }
 public void setWidth(int width) { this.width = width; }

 public int getHeight() { return height; }
 public void setHeight(int height) { this.height = height; }
}
","instruction":"新建 NodeLayout 值对象，承载节点渲染坐标与尺寸，取代原先散落在 MindNode 中的 x/y/width/height 字段。","apply_mode":"apply_only"}},"timestamp":1778216509,"type":"TOOL_CALL_ARGS"}

{"rawEvent":{"message_id":"019e05f66b7e7288907a5d1bcfd79024","conversation_id":"019e05ef837872ff88e884de72bfb068","tool_call_id":"tooluse_DozljQl7M6R4ABkIGhuDHm","document":{"file_path":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/engine/LayoutResult.java","sub_content":"LayoutResult.java","sub_content_event":"open_editor","sub_content_event_value":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/engine/LayoutResult.java","sub_content_tip":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/engine/LayoutResult.java","apply_content":"package mindmap.engine;

import mindmap.model.MindNode;

import java.awt.Rectangle;
import java.util.HashMap;
import java.util.Map;

/**
 * 一次布局的产物：MindNode -> NodeLayout 的映射。
 * 由 LayoutEngine 计算并返回，供视图层消费，取代把坐标塞回 MindNode 的做法。
 */
public final class LayoutResult {
 private final Map<MindNode, NodeLayout> layouts = new HashMap<>();

 public NodeLayout get(MindNode node) {
 return layouts.get(node);
 }

 public NodeLayout getOrCreate(MindNode node) {
 return layouts.computeIfAbsent(node, k -> new NodeLayout());
 }

 public void put(MindNode node, NodeLayout layout) {
 layouts.put(node, layout);
 }

 public boolean contains(MindNode node) {
 return layouts.containsKey(node);
 }

 public int size() {
 return layouts.size();
 }

 /**
 * 计算整棵子树的包围盒（含根节点）。不存在时返回 null。
 */
 public Rectangle computeBounds(MindNode root) {
 NodeLayout rootLayout = layouts.get(root);
 if (rootLayout == null) return null;
 Rectangle rect = new Rectangle(rootLayout.getX(), rootLayout.getY(),
 rootLayout.getWidth(), rootLayout.getHeight());
 addBounds(root, rect);
 return rect;
 }

 private void addBounds(MindNode node, Rectangle rect) {
 for (MindNode c : node.getChildren()) {
 NodeLayout l = layouts.get(c);
 if (l != null) {
 rect.add(new Rectangle(l.getX(), l.getY(), l.getWidth(), l.getHeight()));
 }
 addBounds(c, rect);
 }
 }
}
","instruction":"新建 LayoutResult：承载一次布局计算的所有节点坐标，并提供包围盒工具方法。","apply_mode":"apply_only"}},"timestamp":1778216518,"type":"TOOL_CALL_ARGS"}

