 if (list.isEmpty()) return;

 int totalH = 0;
 int[] heights = new int[list.size()];
 for (int i = 0; i < list.size(); i++) {
 heights[i] = getSubtreeHeight(list.get(i), result);
 totalH += heights[i];
 }
 totalH += (list.size() - 1) * V_GAP;

 int currentY = centerY - totalH / 2;

