{"rawEvent":{"message_id":"019e05f66b7e7288907a5d1bcfd79024","conversation_id":"019e05ef837872ff88e884de72bfb068","tool_call_id":"tooluse_dpy8HN1A8wuwhIcE6yWG6v","document":{"file_path":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/engine/DirectionalLayoutEngine.java","sub_content":"DirectionalLayoutEngine.java","sub_content_event":"open_editor","sub_content_event_value":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/engine/DirectionalLayoutEngine.java","sub_content_tip":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/engine/DirectionalLayoutEngine.java","apply_content":"package mindmap.engine;

import mindmap.model.MindNode;

import java.awt.FontMetrics;

public class DirectionalLayoutEngine extends AutoLayoutEngine {
 @Override
 public LayoutResult calculateLayout(MindNode root, FontMetrics fm, String layoutType) {
 LayoutResult result = new LayoutResult();
 layoutNodeSizes(root, fm, result);

 NodeLayout rootLayout = result.getOrCreate(root);
 rootLayout.setX(-rootLayout.getWidth() / 2);
 rootLayout.setY(-rootLayout.getHeight() / 2);

 if ("Right-Flow".equals(layoutType)) {
 doLayout(root, rootLayout.getX() + rootLayout.getWidth() + H_GAP,
 rootLayout.getY() + rootLayout.getHeight() / 2, true, result);
 } else if ("Left-Flow".equals(layoutType)) {
 doLayout(root, rootLayout.getX() - H_GAP,
 rootLayout.getY() + rootLayout.getHeight() / 2, false, result);
 }
 return result;
 }
}
