{"rawEvent":{"message_id":"019e05f66b7e7288907a5d1bcfd79024","conversation_id":"019e05ef837872ff88e884de72bfb068","tool_call_id":"tooluse_QBBmOma1RmvjcO839O6cYT","document":{"file_path":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/model/ChangeType.java","sub_content":"ChangeType.java","sub_content_event":"open_editor","sub_content_event_value":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/model/ChangeType.java","sub_content_tip":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/model/ChangeType.java","apply_content":"package mindmap.model;

/**
 * Model 变更事件类型。用于细粒度地通知观察者：
 * - STRUCTURE_CHANGED：节点增删、改名、换根 —— 需要重算布局 + 重建侧栏
 * - SELECTION_CHANGED：仅选中节点变化 —— 只需重绘
 * - LAYOUT_CHANGED：布局策略切换 —— 需要重算布局
 * - FILE_CHANGED：当前文件名变化 —— 仅刷新状态栏
 */
public enum ChangeType {
 STRUCTURE_CHANGED,
 SELECTION_CHANGED,
 LAYOUT_CHANGED,
 FILE_CHANGED
}
