{"rawEvent":{"message_id":"019e05f66b7e7288907a5d1bcfd79024","conversation_id":"019e05ef837872ff88e884de72bfb068","tool_call_id":"tooluse_PWJSTMLEnYyyNiAZDvktee","document":{"file_path":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/model/ChangeListener.java","sub_content":"ChangeListener.java","sub_content_event":"open_editor","sub_content_event_value":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/model/ChangeListener.java","sub_content_tip":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/model/ChangeListener.java","apply_content":"package mindmap.model;

import java.util.EnumSet;

/**
 * Model 变更监听器。允许订阅者声明自己关心的事件类型集合。
 */
@FunctionalInterface
public interface ChangeListener {
 void onChange(ChangeType type);

 /** 便捷：仅关注某些事件类型的监听器包装。 */
 static ChangeListener filtered(EnumSet<ChangeType> interested, Runnable action) {
 return type -> {
 if (interested.contains(type)) action.run();
 };
 }
}
