{"rawEvent":{"message_id":"019e05f66b7e7288907a5d1bcfd79024","conversation_id":"019e05ef837872ff88e884de72bfb068","tool_call_id":"tooluse_QrY9KM3itvVcD0Ba5P191T","document":{"file_path":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/ui/MindMapRenderer.java","sub_content":"MindMapRenderer.java","sub_content_event":"open_editor","sub_content_event_value":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/ui/MindMapRenderer.java","sub_content_tip":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/ui/MindMapRenderer.java","apply_content":"package mindmap.ui;

import mindmap.engine.LayoutResult;
import mindmap.engine.NodeLayout;
import mindmap.model.MindNode;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;

/**
 * 纯粹的绘制器：根据 LayoutResult 把思维导图画到任意 Graphics2D 上。
 * 既服务于 DrawingPanel 的屏幕绘制，也服务于 FileHandler.exportImage 的离屏导出，
 * 使得 util 层不再依赖 ui 层的具体组件。
 */
public final class MindMapRenderer {
 private static final int H_GAP = 80;

 private static final Color MAIN_BLUE = new Color(74, 144, 226);
 private static final Color SEL_BG_COLOR = new Color(225, 238, 252);
 private static final Color SEL_BORDER_COLOR = new Color(208, 2, 27);
 private static final Color TEXT_COLOR = new Color(50, 50, 50);

 private MindMapRenderer() {}

 public static void drawConnections(Graphics2D g2, MindNode node, LayoutResult layout) {
 g2.setStroke(new BasicStroke(1.8f));
 g2.setColor(MAIN_BLUE);
 NodeLayout pl = layout.get(node);
 if (pl == null) return;

 for (MindNode child : node.getChildren()) {
 NodeLayout cl = layout.get(child);
 if (cl == null) continue;

 boolean childIsRight = cl.getX() > pl.getX();
 int startX = childIsRight ? pl.getX() + pl.getWidth() : pl.getX();
 int startY = pl.getY() + pl.getHeight() / 2;
 int endX = childIsRight ? cl.getX() : cl.getX() + cl.getWidth();
 int endY = cl.getY() + cl.getHeight() / 2;

 int ctrlX1 = startX + (childIsRight ? H_GAP / 2 : -H_GAP / 2);
 int ctrlX2 = endX - (childIsRight ? H_GAP / 2 : -H_GAP / 2);

 Path2D path = new Path2D.Double();
 path.moveTo(startX, startY);
 path.curveTo(ctrlX1, startY, ctrlX2, endY, endX, endY);
 g2.draw(path);

 drawConnections(g2, child, layout);
 }
 }

 public static void drawNodes(Graphics2D g2, MindNode node, LayoutResult layout, MindNode selected) {
 for (MindNode child : node.getChildren()) drawNodes(g2, child, layout, selected);

 NodeLayout l = layout.get(node);
 if (l == null) return;

 boolean isSel = (node == selected);
 g2.setColor(isSel ? SEL_BG_COLOR : Color.WHITE);
 g2.fillRoundRect(l.getX(), l.getY(), l.getWidth(), l.getHeight(), 14, 14);

 g2.setStroke(new BasicStroke(isSel ? 2.5f : 1.5f));
 g2.setColor(isSel ? SEL_BORDER_COLOR : MAIN_BLUE);
 g2.drawRoundRect(l.getX(), l.getY(), l.getWidth(), l.getHeight(), 14, 14);

 g2.setColor(TEXT_COLOR);
 g2.setFont(g2.getFont().deriveFont(isSel ? Font.BOLD : Font.PLAIN, 14f));
 FontMetrics fm = g2.getFontMetrics();
 int tx = l.getX() + 18;
 int ty = l.getY() + 12 + fm.getAscent();
 g2.drawString(node.getText(), tx, ty);
 }
}
","instruction":"新建 MindMapRenderer：承担所有绘制逻辑（原先是 DrawingPanel.drawConnections / drawNodes），以便 FileHandler.exportImage 不再依赖 DrawingPanel。","apply_mode":"apply_only"}},"timestamp":1778216611,"type":"TOOL_CALL_ARGS"}

{"rawEvent":{"message_id":"019e05f66b7e7288907a5d1bcfd79024","conversation_id":"019e05ef837872ff88e884de72bfb068","tool_call_id":"tooluse_09qZPfDIguHS9Rpg7LE6wC","document":{"file_path":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/ui/DrawingPanel.java","sub_content":"DrawingPanel.java","sub_content_event":"open_editor","sub_content_event_value":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/ui/DrawingPanel.java","sub_content_tip":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/ui/DrawingPanel.java","apply_content":"package mindmap.ui;

import mindmap.engine.AutoLayoutEngine;
import mindmap.engine.DirectionalLayoutEngine;
import mindmap.engine.LayoutManager;
import mindmap.engine.LayoutResult;
import mindmap.engine.NodeLayout;
import mindmap.model.ChangeType;
import mindmap.model.MindMapModel;
import mindmap.model.MindNode;

import javax.swing.JPanel;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.RenderingHints;
import java.awt.event.ComponentAdapter;
import java.awt.event.ComponentEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionAdapter;
import java.awt.geom.AffineTransform;

public class DrawingPanel extends JPanel {
 private final MindMapModel model;

 private double scale = 1.0;
 private double translateX = 0, translateY = 0;
 private Point lastMousePt;

 private boolean layoutDirty = true;
 private LayoutResult layoutResult;

 private static final Color BG_COLOR = new Color(245, 247, 250);

 public DrawingPanel(MindMapModel model) {
 this.model = model;
 setBackground(BG_COLOR);
 setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

 // 只有结构或布局策略变化时才需要重算布局；选中变化只重绘。
 model.addChangeListener(type -> {
 if (type == ChangeType.STRUCTURE_CHANGED || type == ChangeType.LAYOUT_CHANGED) {
 layoutDirty = true;
 }
 if (type != ChangeType.FILE_CHANGED) {
 repaint();
 }
 });

 initInteractions();
 }

 public Color getBgColor() { return BG_COLOR; }

 /** 提供给外部（如 exportImage）的布局结果访问。若尚未计算，返回 null。 */
 public LayoutResult getLayoutResult() { return layoutResult; }

 /** 供导出图片时使用：在给定 FontMetrics 下同步计算一次布局并返回结果。 */
 public LayoutResult computeLayout(FontMetrics fm) {
 LayoutManager engine = createEngine(model.getCurrentLayout());
 layoutResult = engine.calculateLayout(model.getRoot(), fm, model.getCurrentLayout());
 layoutDirty = false;
 return layoutResult;
 }

 public void resetTransform() {
 translateX = getWidth() / 2.0;
 translateY = getHeight() / 2.0;
 scale = 1.0;
 repaint();
 }

 private LayoutManager createEngine(String layoutType) {
 return "Balanced".equals(layoutType) ? new AutoLayoutEngine() : new DirectionalLayoutEngine();
 }

 private void initInteractions() {
 addMouseListener(new MouseAdapter() {
 public void mousePressed(MouseEvent e) {
 lastMousePt = e.getPoint();
 int worldX = (int) ((e.getX() - translateX) / scale);
 int worldY = (int) ((e.getY() - translateY) / scale);

 if (layoutResult == null) return;
 MindNode clicked = findNodeAt(model.getRoot(), worldX, worldY);
 if (clicked != null) {
 model.setSelectedNode(clicked);
 }
 }
 });

 addMouseMotionListener(new MouseMotionAdapter() {
 public void mouseDragged(MouseEvent e) {
 if (lastMousePt != null) {
 translateX += e.getX() - lastMousePt.x;
 translateY += e.getY() - lastMousePt.y;
 lastMousePt = e.getPoint();
 repaint();
 }
 }
 });

 addMouseWheelListener(e -> {
 double oldScale = scale;
 if (e.getWheelRotation() < 0) scale *= 1.1;
 else scale /= 1.1;
 scale = Math.max(0.2, Math.min(scale, 5.0));
 double scaleChange = scale / oldScale;
 translateX = e.getX() - scaleChange * (e.getX() - translateX);
 translateY = e.getY() - scaleChange * (e.getY() - translateY);
 repaint();
 });

 addComponentListener(new ComponentAdapter() {
 public void componentResized(ComponentEvent e) {
 if (translateX == 0 && translateY == 0 && getWidth() > 0) {
 translateX = getWidth() / 2.0;
 translateY = getHeight() / 2.0;
 }
 }
 });
 }

 @Override
 protected void paintComponent(Graphics g) {
 super.paintComponent(g);
 Graphics2D g2 = (Graphics2D) g.create();
 try {
 g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
 g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

 if ((layoutDirty || layoutResult == null) && model.getRoot() != null) {
 FontMetrics fm = g2.getFontMetrics(g2.getFont().deriveFont(Font.BOLD, 14f));
 LayoutManager engine = createEngine(model.getCurrentLayout());
 layoutResult = engine.calculateLayout(model.getRoot(), fm, model.getCurrentLayout());
 layoutDirty = false;
 }

 AffineTransform original = g2.getTransform();
 AffineTransform at = new AffineTransform(original);
 at.translate(translateX, translateY);
 at.scale(scale, scale);
 g2.setTransform(at);

 if (model.getRoot() != null && layoutResult != null) {
 MindMapRenderer.drawConnections(g2, model.getRoot(), layoutResult);
 MindMapRenderer.drawNodes(g2, model.getRoot(), layoutResult, model.getSelectedNode());
 }

 g2.setTransform(original);
 } finally {
 g2.dispose();
 }
 }

 private MindNode findNodeAt(MindNode node, int mx, int my) {
 NodeLayout l = layoutResult.get(node);
 if (l != null
 && mx >= l.getX() && mx <= l.getX() + l.getWidth()
 && my >= l.getY() && my <= l.getY() + l.getHeight()) {
 return node;
 }
 for (MindNode child : node.getChildren()) {
 MindNode found = findNodeAt(child, mx, my);
 if (found != null) return found;
 }
 return null;
 }
}
","instruction":"重写 DrawingPanel：使用 LayoutResult 替代原先写在 MindNode 上的坐标；绘制委托给 MindMapRenderer；监听改为 ChangeType 分发（选中变化不重算布局）；paintComponent 使用 g.create() / dispose() 保证变换隔离。提供 computeLayout 给 FileHandler.exportImage 复用。","apply_mode":"apply_only"}},"timestamp":1778216626,"type":"TOOL_CALL_ARGS"}

