{"rawEvent":{"message_id":"019e05fdcdeb77939e39095b9e23a216","conversation_id":"019e05ef837872ff88e884de72bfb068","tool_call_id":"tooluse_kZfL6MEBDD2iqHtnRBcqHA","document":{"file_path":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/engine/LayoutEngine.java","sub_content":"LayoutEngine.java","sub_content_event":"open_editor","sub_content_event_value":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/engine/LayoutEngine.java","sub_content_tip":"C:/Users/viperwu/IdeaProjects/MindMap/src/main/java/mindmap/engine/LayoutEngine.java","apply_content":"package mindmap.engine;

import mindmap.model.MindNode;

import java.awt.FontMetrics;

/**
 * 布局策略接口。给定一棵思维导图的根节点和字体度量，
 * 计算并返回一个 {@link LayoutResult}（不产生副作用、不回写到 MindNode）。
 *
 * <p>之所以不再叫 LayoutManager：是为避免与 {@link java.awt.LayoutManager} 同名歧义。
 */
public interface LayoutEngine {
